{
  "title": "Actualisation des enveloppes pluriannuelles pour les grands projets de la ville",
  "summary": "Le Conseil municipal ajuste les enveloppes financières pluriannuelles (autorisations de programme et crédits de paiement) pour quatre grands projets d'investissement de la commune en 2026, actant notamment une diminution pour la construction du groupe scolaire Prévert.",
  "topic_tag": "Budget",
  "is_substantial": true,
  "acronyms": {
    },
  "analysis_data": {
    "contexte": "Le conseil municipal gère ses dépenses d'équipement sur plusieurs années par le biais d'Autorisations de Programme (AP, enveloppes globales autorisant à engager des projets) et de Crédits de Paiement (CP, sommes payables pour l'année en cours). Une mise à jour est présentée dans le cadre de la décision modificative budgétaire.",
    "decision": "Le conseil municipal approuve l'actualisation et la révision de la répartition des crédits des quatre autorisations de programme de la commune pour l'exercice 2026.",
    "impacts": "Néant",
    "points_debattus": "L'ajustement budgétaire a fait l'objet d'un vote adopté à la majorité, avec l'abstention de neuf conseillers municipaux."
  },
  "budget_impact": 0,
  "budget_type": "AUCUN",
  "budget_note": "",
  "budget_breakdown": [],
  "budget_changes": [
    {
      "scope": "AP",
      "direction": "BAISSE",
      "label": "Création Groupe scolaire Prévert",
      "amount": 500000,
      "period": "2026"
    },
    {
      "scope": "CP",
      "direction": "BAISSE",
      "label": "Création Groupe scolaire Prévert",
      "amount": 200000,
      "period": "2026"
    },
    {
      "scope": "CP",
      "direction": "BAISSE",
      "label": "Création d'un Complexe Sportif Polyvalent",
      "amount": 1000000,
      "period": "2026"
    }
  ],
  "climate_impact": "neutre",
  "key_points": [
    "Révision à la baisse de 500 000 euros de l'enveloppe globale de l'autorisation de programme du groupe scolaire Prévert.",
    "Ajustement des crédits de paiement de l'exercice 2026 pour le groupe scolaire Prévert (-200 000 euros) et pour le complexe sportif polyvalent (-1 000 000 euros).",
    "Le bilan concerne quatre grands projets : la cuisine municipale, l'école Prévert, le complexe sportif polyvalent et l'extension du restaurant scolaire Joliot Curie."
  ],
  "vote": {
    "has_vote": true,
    "pour": 30,
    "contre": 0,
    "abstention": 9
  },
  "disagreements": "Neuf élus se sont abstenus lors du vote de la délibération : Mme Edwige LUCBERNET, Mme Marie-Laure PIROTH, Mme Marie JANVIER, M. Julien LEFEBVRE, M. Vincent BOIVINET, Mme Aurélie BOUSQUET, M. Rémi JOUSSIAUME, M. Pierre OUALLET et M. Clément ROSSIGNOL PUECH.",
  "critical_facts": [
    {
      "id": "dec_01",
      "kind": "DECISION",
      "audience": "SITE",
      "label": "Approbation du bilan de l'actualisation et de la révision des autorisations de programme et des crédits de paiement",
      "status": "ADOPTE",
      "evidence": {
        "page": 3,
        "excerpt": "Article 1 : D’approuver, conformément à l’annexe jointe à la délibération, le bilan de l’actualisation et la révision des autorisations de programme et des crédits de paiement."
      }
    },
    {
      "id": "vote_01",
      "kind": "VOTE",
      "audience": "SITE",
      "label": "Vote du conseil municipal sur l'actualisation des AP et CP",
      "status": "ADOPTE",
      "evidence": {
        "page": 3,
        "excerpt": "Pour 30, Abstentions 9"
      },
      "vote": {
        "for": 30,
        "against": 0,
        "abstain": 9
      }
    },
    {
      "id": "fin_01",
      "kind": "FINANCE",
      "audience": "EXTRACTION",
      "label": "Révision de l'AP pour la création du groupe scolaire Prévert",
      "status": "ADOPTE",
      "evidence": {
        "page": 4,
        "excerpt": "- 500 000 €"
      },
      "money": {
        "cents": -50000000,
        "category": "AP",
        "role": "COMPOSANTE"
      }
    }
  ]
}

